actions.script:
def _valid = ['kpis','arap','revexp']
def _clean = ((context.order ?: '').toString().split(',') as List).findAll { _valid.contains(it) }
ec.user.setPreference('ACCT_DASH_ORDER', _clean.join(','))
if (context.sizes != null) {
    def _sz = ((context.sizes ?: '').toString().split(',') as List)
            .collect { it.split(':') as List }
            .findAll { it.size()==2 && _valid.contains(it[0]) && it[1]=='half' }
            .collect { it[0]+':half' }
    ec.user.setPreference('ACCT_DASH_SIZE', _sz.join(','))
}
ec.web.sendJsonResponse([saved:true, order:_clean.join(',')])

def sdf = new java.text.SimpleDateFormat("yyyy-MM-dd")
def now = ec.user.nowTimestamp
def todayStr = sdf.format(now)
def _cw = java.util.Calendar.getInstance(); _cw.setTime(now); _cw.set(java.util.Calendar.DAY_OF_WEEK, _cw.getFirstDayOfWeek()); def weekStartStr = sdf.format(_cw.getTime())
def _cm = java.util.Calendar.getInstance(); _cm.setTime(now); _cm.set(java.util.Calendar.DAY_OF_MONTH,1); def monthStartStr = sdf.format(_cm.getTime())
def _yc = java.util.Calendar.getInstance(); _yc.setTime(now); _yc.set(java.util.Calendar.MONTH,0); _yc.set(java.util.Calendar.DAY_OF_MONTH,1); def yearStartStr = sdf.format(_yc.getTime())
if (!dashDate) dashDate = weekStartStr
if (!dashDateTo) dashDateTo = todayStr
if (dashDateTo < dashDate) { def _s = dashDate; dashDate = dashDateTo; dashDateTo = _s }
dayStart = java.sql.Timestamp.valueOf(dashDate + " 00:00:00")
def _ce = java.util.Calendar.getInstance(); _ce.setTime(java.sql.Timestamp.valueOf(dashDateTo + " 00:00:00")); _ce.add(java.util.Calendar.DAY_OF_MONTH, 1)
dayEndExcl = new java.sql.Timestamp(_ce.getTimeInMillis())
def rangeShort = new java.text.SimpleDateFormat("dd MMM")
def rangeLong = new java.text.SimpleDateFormat("dd MMM yyyy")
rangeDisplay = (dashDate.substring(0,4) == dashDateTo.substring(0,4) ? rangeShort : rangeLong).format(java.sql.Date.valueOf(dashDate)) + ' – ' + rangeLong.format(java.sql.Date.valueOf(dashDateTo))
urlToday = "?dashDate="+todayStr+"&dashDateTo="+todayStr
urlWeek = "?dashDate="+weekStartStr+"&dashDateTo="+todayStr
urlMonth = "?dashDate="+monthStartStr+"&dashDateTo="+todayStr
urlYear = "?dashDate="+yearStartStr+"&dashDateTo="+todayStr
presetActive = dashDateTo == todayStr ?
    (dashDate == todayStr ? 'today' : dashDate == weekStartStr ? 'week' : dashDate == monthStartStr ? 'month' : dashDate == yearStartStr ? 'year' : 'custom') : 'custom'
showCustom = (dateMode ?: '') == 'custom'
urlSettings = "?dashDate="+dashDate+"&dashDateTo="+dashDateTo+"&showSettings=1"

// All visible amounts come from the active organization's unpaid invoices. def unpaid = { inv -> def amount = ((inv.unpaidTotal != null ? inv.unpaidTotal : inv.invoiceTotal) ?: 0) as BigDecimal amount > 0 ? amount : BigDecimal.ZERO } arOpen = arList.findAll { unpaid(it) > 0 } apOpen = apList.findAll { unpaid(it) > 0 } totalAr = arOpen.sum { unpaid(it) } ?: BigDecimal.ZERO totalAp = apOpen.sum { unpaid(it) } ?: BigDecimal.ZERO arCount = arOpen.size() apVendorCount = apOpen.collect { it.fromPartyId }.findAll { it }.unique().size() arDisplay = zinr.inr(ec.l10n.format(totalAr, '#,##,##0.00')) apDisplay = zinr.inr(ec.l10n.format(totalAp, '#,##,##0.00'))
long dayMs = 86400000L int spanDays = Math.max(1, ((dayEndExcl.time - dayStart.time) / dayMs) as int) int barCount = Math.min(8, spanDays) def chartDateFmt = new java.text.SimpleDateFormat('dd MMM') chartBars = (0..<barCount).collect { idx -> long startOffset = Math.floor(idx * spanDays / (double) barCount) as long [label:chartDateFmt.format(new java.util.Date(dayStart.time + startOffset * dayMs)), ar:BigDecimal.ZERO, ap:BigDecimal.ZERO] } def fillChart = { invoices, key -> invoices.each { inv -> def d = inv.invoiceDate ?: inv.entryDate if (d && d.time >= dayStart.time && d.time < dayEndExcl.time) { int offset = ((d.time - dayStart.time) / dayMs) as int int idx = Math.min(barCount - 1, (offset * barCount / spanDays) as int) chartBars[idx][key] += unpaid(inv) } } } fillChart(arOpen, 'ar') fillChart(apOpen, 'ap') def maxBar = (chartBars.collectMany { [it.ar, it.ap] }.max() ?: BigDecimal.ZERO) as BigDecimal chartMax = maxBar > 0 ? maxBar : BigDecimal.ONE chartBars.each { b -> b.arPct = b.ar > 0 ? Math.max(3, ((b.ar * 100 / chartMax) as BigDecimal).intValue()) : 0 b.apPct = b.ap > 0 ? Math.max(3, ((b.ap * 100 / chartMax) as BigDecimal).intValue()) : 0 } chartAxis = (4..0).collect { n -> def value = maxBar * n / 4 value >= 100000 ? '₹' + ec.l10n.format(value / 100000, '#0.#') + 'L' : '₹' + ec.l10n.format(value, '#,##0') } def spark = { key, color -> def values = chartBars.collect { (it[key] ?: 0) as BigDecimal } def maxValue = values.max() ?: BigDecimal.ONE if (maxValue == 0) maxValue = BigDecimal.ONE def points = values.withIndex().collect { pair -> def v = pair[0] def i = pair[1] def x = values.size() == 1 ? 140 : (i * 280.0 / (values.size() - 1)) def y = 55.0 - (v.doubleValue() / maxValue.doubleValue()) * 45.0 String.format(java.util.Locale.US, '%.1f,%.1f', x, y) }.join(' ') '<svg viewBox="0 0 280 65" aria-hidden="true"><polyline points="'+points+'" fill="none" stroke="'+color+'" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"/></svg>' } arSparkSvg = spark('ar', '#16b647') apSparkSvg = spark('ap', '#ff7a00')
def age = { invoices -> def rows = [ [label:'0 – 30 Days', color:'#21bb62', count:0, amount:BigDecimal.ZERO], [label:'31 – 60 Days', color:'#56ca75', count:0, amount:BigDecimal.ZERO], [label:'61 – 90 Days', color:'#ff8917', count:0, amount:BigDecimal.ZERO], [label:'90+ Days', color:'#f05252', count:0, amount:BigDecimal.ZERO] ] invoices.each { inv -> def due = inv.dueDate ?: inv.invoiceDate ?: inv.entryDate ?: now int late = Math.max(0, ((now.time - due.time) / dayMs) as int) int idx = late <= 30 ? 0 : late <= 60 ? 1 : late <= 90 ? 2 : 3 rows[idx].count++ rows[idx].amount += unpaid(inv) } rows.each { row -> row.amountText = zinr.inr(ec.l10n.format(row.amount, '#,##,##0.00')) } rows } arAgingRows = age(arOpen) apAgingRows = age(apOpen)

def _roleHidden = ''
try {
    if (!ec.user.isInGroup("ADMIN")) {
        def _zrp = (ec.user.userGroupIdSet ?: []).findAll { it?.startsWith("ZENITH_") && it != "ZENITH_ALL" }
        if (_zrp.size() == 1 && _zrp.contains("ZENITH_CASHIER")) _roleHidden = 'arap,revexp'
    }
} catch (Exception e) {}
def _pref = ec.user.getPreference('ACCT_DASH_HIDDEN')
def _hiddenSet = ((_pref != null) ? _pref : _roleHidden).split(',').findAll { it }.toSet()
showKpis = !_hiddenSet.contains('kpis'); showArap = !_hiddenSet.contains('arap')
w_kpis = showKpis ? 'Y' : ''; w_arap = showArap ? 'Y' : ''
dashOrderCsv = (ec.user.getPreference('ACCT_DASH_ORDER') ?: '')
dashSizeCsv = (ec.user.getPreference('ACCT_DASH_SIZE') ?: '')
urlSettings = dashDate ? ("?dashDate="+dashDate+"&dashDateTo="+dashDateTo+"&showSettings=1") : "?showSettings=1"
